module alternating_sum (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] a,\n    input wire [7:0] b,\n    input wire [3:0] k,\n    input wire [7:0] s_sequence,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State parameters\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_R = 3'd1;\n    localparam [2:0] COMPUTE_C = 3'd2;\n    localparam [2:0] COMPUTE_D = 3'd3;\n    localparam [2:0] COMPUTE_RESULT = 3'd4;\n    localparam [2:0] COMPLETE = 3'd5;\n\n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [3:0] counter;\n    reg [3:0] bit_pos;\n    reg [15:0] sum;\n    reg [7:0] r;\n    reg [7:0] r_k;\n    reg [7:0] current_r;\n    reg [7:0] base;\n    reg [15:0] C;\n    reg [15:0] D;\n    reg [15:0] a_pow_n;\n\n    // Combinational logic\n    wire [7:0] s_bit = (s_sequence >> bit_pos) & 8'h01;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            counter <= 4'd0;\n            bit_pos <= 4'd0;\n            sum <= 16'd0;\n            r <= 8'd0;\n            r_k <= 8'd0;\n            current_r <= 8'd0;\n            base <= 8'd0;\n            C <= 16'd0;\n            D <= 16'd0;\n            a_pow_n <= 16'd0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        r <= (b * 8'hFF) / a;  // Q8.8 approximation\n                        current_r <= 8'h01;    // r^0 = 1\n                        counter <= k;\n                        bit_pos <= 4'd0;\n                        sum <= 16'd0;\n                        r_k <= 8'h01;\n                        base <= (b * 8'hFF) / a;\n                        next_state <= COMPUTE_R;\n                    end\n                end\n\n                COMPUTE_R: begin\n                    if (counter > 0) begin\n                        r_k <= (r_k * base) >> 8;  // Fixed-point multiplication\n                        counter <= counter - 4'd1;\n                    end else begin\n                        current_r <= 8'h01;\n                        bit_pos <= 4'd0;\n                        sum <= 16'd0;\n                        next_state <= COMPUTE_C;\n                    end\n                end\n\n                COMPUTE_C: begin\n                    if (bit_pos < k) begin\n                        sum <= sum + (s_bit[0] ? current_r : -current_r);\n                        current_r <= (current_r * r) >> 8;\n                        bit_pos <= bit_pos + 4'd1;\n                    end else begin\n                        C <= sum;\n                        current_r <= 8'h01;\n                        counter <= 4'd0;\n                        sum <= 16'd0;\n                        next_state <= COMPUTE_D;\n                    end\n                end\n\n                COMPUTE_D: begin\n                    if (counter < k) begin\n                        sum <= sum + current_r;\n                        current_r <= (current_r * r_k) >> 8;\n                        counter <= counter + 4'd1;\n                    end else begin\n                        D <= sum;\n                        a_pow_n <= a;  // Simplified a^n approximation\n                        next_state <= COMPUTE_RESULT;\n                    end\n                end\n\n                COMPUTE_RESULT: begin\n                    result <= (a_pow_n * C * D) >> 8;  // Fixed-point scaling\n                    next_state <= COMPLETE;\n                end\n\n                COMPLETE: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule